def invoke_endpoint_async(self) -> TYPE_RESPONSE:
    endpoint_name = self.path.split("/")[2]
    input_location = self.headers.get("X-Amzn-SageMaker-InputLocation")
    inference_id = self.headers.get("X-Amzn-SageMaker-Inference-Id")

    # Get the output location
    location = self.sagemakerruntime_backend.invoke_endpoint_async(
        endpoint_name, input_location
    )

    # Get the failure location if it exists
    failure_location = None
    if endpoint_name in self.sagemakerruntime_backend.async_failure_results:
        if input_location in self.sagemakerruntime_backend.async_failure_results[endpoint_name]:
            failure_location = self.sagemakerruntime_backend.async_failure_results[endpoint_name][input_location]

    resp = {"InferenceId": inference_id or str(random.uuid4())}
    headers = {"X-Amzn-SageMaker-OutputLocation": location}

    # Add failure location to headers if it exists
    if failure_location:
        headers["X-Amzn-SageMaker-FailureLocation"] = failure_location

    return 200, headers, json.dumps(resp)

